import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";var i=JSON.parse(`{"title":"Insecure HTTP cookies","description":"","frontmatter":{"search":{"exclude":true}},"headers":[],"relativePath":"d/web/insecure-http-cookies.md","filePath":"d/web/insecure-http-cookies.md","lastUpdated":1781102819000}`),a={name:`d/web/insecure-http-cookies.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /d/web/insecure-http-cookies.md for this page in Markdown format</div><h1 id="insecure-http-cookies" tabindex="-1">Insecure HTTP cookies <a class="header-anchor" href="#insecure-http-cookies" aria-label="Permalink to “Insecure HTTP cookies”">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to “Description”">​</a></h2><p>HTTP is a stateless protocol, meaning it cannot distinguish requests from different users without an additional mechanism. Addressing this problem requires a session mechanism. The most commonly used mechanism for managing HTTP sessions in browsers is cookie storage. An HTTP cookie is a small record that a server sends to a user&#39;s web browser. The browser can store the cookie and send it back to the same server for subsequent requests. Web applications can thus implement sessions for the stateless HTTP protocol. The server can use the HTTP cookie to distinguish requests from different users and to keep users logged in.</p><p>Cookies thus represent a frequent target for attackers. A web application should, therefore, harden the configuration of all sensitive cookies by setting the <code>Secure</code> and <code>HttpOnly</code> cookie attributes and the <code>SameSite</code> attribute to <code>strict</code>:</p><ul><li>A cookie with the <code>Secure</code> attribute will only be sent to the server over HTTPS connections and never over an unsecured HTTP connection.</li><li>A cookie with the <code>HttpOnly</code> attribute set is inaccessible to JavaScript and thus helps mitigate cross-site scripting (XSS) attacks.</li><li>A cookie with <code>SameSite=strict</code> attribute will not be sent in cross-site requests from third-party websites (in contrast to the weaker <code>Lax</code> and the insecure <code>None</code>).</li></ul><p>If an attacker can tap sensitive cookies such as session cookies, the attacker could take over user accounts and perform actions in the context of affected users. An attacker may also gain complete control over all web application functions and data if they take over a user account with privileged access.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to “Recommendation”">​</a></h2><p>Set the cookie attributes <code>HttpOnly</code>, <code>Secure</code>, and <code>SameSite=Strict</code>.</p>`,9)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};